INSERT INTO subtopics (id, topic_id, title, description, sort_order, skill_id) VALUES
  ('51000000-0000-0000-0000-000000030101', '41000000-0000-0000-0000-000000000301', 'Place value to tens of thousands', 'Reads, writes and partitions numbers up to tens of thousands.', 1, 'ma2-place-value'),
  ('51000000-0000-0000-0000-000000030201', '41000000-0000-0000-0000-000000000302', 'Adding and subtracting', 'Adds and subtracts 2- to 4-digit numbers using written and mental strategies.', 1, 'ma2-add-sub'),
  ('51000000-0000-0000-0000-000000030202', '41000000-0000-0000-0000-000000000302', 'Missing numbers in + and −', 'Finds the missing number in addition and subtraction number sentences.', 2, 'ma2-missing-addend'),
  ('51000000-0000-0000-0000-000000030301', '41000000-0000-0000-0000-000000000303', 'Times tables to 10 × 10', 'Recalls multiplication facts up to 10 × 10.', 1, 'ma2-times-tables'),
  ('51000000-0000-0000-0000-000000030401', '41000000-0000-0000-0000-000000000304', 'Telling the time', 'Reads analog and digital times and works out how long things take.', 1, NULL),
  ('51000000-0000-0000-0000-000000040101', '41000000-0000-0000-0000-000000000401', 'Division facts', 'Uses multiplication facts to divide.', 1, 'ma2-division-facts'),
  ('51000000-0000-0000-0000-000000040102', '41000000-0000-0000-0000-000000000401', 'Missing numbers in × and ÷', 'Finds the missing number in multiplication and division number sentences.', 2, 'ma2-missing-factor'),
  ('51000000-0000-0000-0000-000000040201', '41000000-0000-0000-0000-000000000402', 'Equivalent fractions', 'Recognises equivalent fractions with denominators 2, 4, 8, 3, 6, 5 and 10.', 1, 'ma2-equivalent-fractions'),
  ('51000000-0000-0000-0000-000000040202', '41000000-0000-0000-0000-000000000402', 'Tenths and hundredths', 'Writes and compares decimals to two decimal places.', 2, 'ma2-decimals'),
  ('51000000-0000-0000-0000-000000040301', '41000000-0000-0000-0000-000000000403', '2D shapes', 'Names 2D shapes and describes them by their sides and angles.', 1, NULL),
  ('51000000-0000-0000-0000-000000050101', '41000000-0000-0000-0000-000000000501', 'Large numbers and rounding', 'Works with numbers into the millions and rounds to a given place.', 1, 'ma3-large-numbers'),
  ('51000000-0000-0000-0000-000000050201', '41000000-0000-0000-0000-000000000502', 'Multiplying larger numbers', 'Multiplies 2- and 3-digit numbers by 1- and 2-digit numbers.', 1, 'ma3-multiply'),
  ('51000000-0000-0000-0000-000000050202', '41000000-0000-0000-0000-000000000502', 'Dividing with remainders', 'Divides 3-digit numbers by 1-digit numbers and records remainders.', 2, 'ma3-divide-remainders'),
  ('51000000-0000-0000-0000-000000050301', '41000000-0000-0000-0000-000000000503', 'Decimals to thousandths', 'Compares and orders decimals to three decimal places.', 1, 'ma3-decimals'),
  ('51000000-0000-0000-0000-000000050302', '41000000-0000-0000-0000-000000000503', 'Adding and subtracting decimals', 'Adds and subtracts decimals with up to two decimal places.', 2, 'ma3-add-sub-decimals'),
  ('51000000-0000-0000-0000-000000050303', '41000000-0000-0000-0000-000000000503', 'Comparing and ordering decimals', 'Compares and orders decimals using place value.', 3, NULL),
  ('51000000-0000-0000-0000-000000060101', '41000000-0000-0000-0000-000000000601', 'Order of operations', 'Uses brackets, ×, ÷, + and − in the correct order.', 1, 'ma3-order-of-operations'),
  ('51000000-0000-0000-0000-000000060201', '41000000-0000-0000-0000-000000000602', 'Adding and subtracting fractions', 'Adds and subtracts fractions with the same or related denominators.', 1, 'ma3-add-fractions'),
  ('51000000-0000-0000-0000-000000060202', '41000000-0000-0000-0000-000000000602', 'Fraction of a quantity', 'Finds a fraction of a whole number, such as 3/4 of 20.', 2, 'ma3-fraction-of-quantity'),
  ('51000000-0000-0000-0000-000000060203', '41000000-0000-0000-0000-000000000602', 'Percentages of amounts', 'Finds 10%, 25%, 50% and 75% of amounts, including money.', 3, 'ma3-percentages'),
  ('51000000-0000-0000-0000-000000060301', '41000000-0000-0000-0000-000000000603', 'Angles', 'Names types of angles and uses angle facts to find unknown angles.', 1, NULL),
  ('51000000-0000-0000-0000-000000031101', '41000000-0000-0000-0000-000000000311', 'Spelling patterns', 'Spells words with common vowel teams, suffixes and silent letters.', 1, 'en2-spelling'),
  ('51000000-0000-0000-0000-000000031201', '41000000-0000-0000-0000-000000000312', 'Word meanings', 'Works out what words mean, including synonyms and antonyms.', 1, 'en2-vocabulary'),
  ('51000000-0000-0000-0000-000000031301', '41000000-0000-0000-0000-000000000313', 'Reading for meaning', 'Finds information, makes inferences and explains word choices in a text.', 1, 'en2-comprehension'),
  ('51000000-0000-0000-0000-000000031401', '41000000-0000-0000-0000-000000000314', 'Capital letters and full stops', 'Uses capital letters and end punctuation correctly.', 1, NULL),
  ('51000000-0000-0000-0000-000000041101', '41000000-0000-0000-0000-000000000411', 'Writing a story', 'Plans and writes a short story with a clear problem and resolution.', 1, 'en2-imaginative'),
  ('51000000-0000-0000-0000-000000041102', '41000000-0000-0000-0000-000000000411', 'Writing to persuade', 'States an opinion and backs it with reasons in paragraphs.', 2, 'en2-persuasive'),
  ('51000000-0000-0000-0000-000000041201', '41000000-0000-0000-0000-000000000412', 'Nouns, verbs and adjectives', 'Identifies nouns, verbs and adjectives in sentences.', 1, NULL),
  ('51000000-0000-0000-0000-000000041202', '41000000-0000-0000-0000-000000000412', 'Building sentences', 'Puts words and events in a sensible order.', 2, NULL),
  ('51000000-0000-0000-0000-000000051101', '41000000-0000-0000-0000-000000000511', 'Spelling with prefixes and suffixes', 'Uses base words, prefixes, suffixes and word origins to spell.', 1, 'en3-spelling'),
  ('51000000-0000-0000-0000-000000051201', '41000000-0000-0000-0000-000000000512', 'Precise vocabulary', 'Chooses precise words and understands figurative language.', 1, 'en3-vocabulary'),
  ('51000000-0000-0000-0000-000000051301', '41000000-0000-0000-0000-000000000513', 'Inference and author''s purpose', 'Infers meaning, identifies the author''s purpose and evaluates texts.', 1, 'en3-comprehension'),
  ('51000000-0000-0000-0000-000000051401', '41000000-0000-0000-0000-000000000514', 'Apostrophes', 'Uses apostrophes for contractions and to show belonging.', 1, NULL),
  ('51000000-0000-0000-0000-000000061101', '41000000-0000-0000-0000-000000000611', 'Writing to inform', 'Writes an organised informative text with topic sentences and facts.', 1, 'en3-informative'),
  ('51000000-0000-0000-0000-000000061102', '41000000-0000-0000-0000-000000000611', 'Persuasive essays', 'Writes a persuasive text with an introduction, arguments, evidence and conclusion.', 2, 'en3-persuasive'),
  ('51000000-0000-0000-0000-000000061201', '41000000-0000-0000-0000-000000000612', 'Figurative language', 'Recognises similes, metaphors, personification and onomatopoeia.', 1, NULL)
INSERT INTO questions (id, subtopic_id, difficulty, points, question_text, question_type, answer_options, correct_answer, explanation, created_by) VALUES
  ('61000000-0000-0000-0000-000003040101', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'The minute hand points to the 6 and the hour hand is halfway between the 3 and the 4. What time is it?', 'multiple_choice', '[{"id":"a","text":"6:30"},{"id":"b","text":"3:30"},{"id":"c","text":"4:30"},{"id":"d","text":"3:06"}]'::jsonb, '"b"'::jsonb, 'When the minute hand points to the 6, it''s half past. The hour hand has passed the 3, so it''s half past 3, or 3:30.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040102', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'How many minutes are there in 1 hour?', 'short_answer', NULL, '"60"'::jsonb, 'There are 60 minutes in 1 hour.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040103', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'How many minutes are there from 2:15 to 2:45?', 'short_answer', NULL, '"30"'::jsonb, 'From 15 minutes past to 45 minutes past is 45 − 15 = 30 minutes.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040104', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'Quarter past 7 is the same time as 7:15.', 'true_false', NULL, '"true"'::jsonb, 'A quarter of an hour is 15 minutes, so quarter past 7 is 7:15.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040105', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'Put these morning times in order, from earliest to latest.', 'ordering', '[{"id":"a","text":"7:05"},{"id":"b","text":"7:50"},{"id":"c","text":"8:30"},{"id":"d","text":"9:45"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Compare the hours first, then the minutes: 7:05, 7:50, 8:30, 9:45.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040106', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'There are ___ days in a week.', 'fill_blank', NULL, '["7","seven"]'::jsonb, 'A week has 7 days, Monday to Sunday.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030101', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'Which of these shapes have exactly 4 sides? Choose all that apply.', 'multi_select', '[{"id":"a","text":"square"},{"id":"b","text":"triangle"},{"id":"c","text":"rectangle"},{"id":"d","text":"pentagon"},{"id":"e","text":"rhombus"}]'::jsonb, '["a","c","e"]'::jsonb, 'Squares, rectangles and rhombuses all have 4 sides. A triangle has 3 and a pentagon has 5.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030102', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'How many sides does a hexagon have?', 'short_answer', NULL, '["6","six"]'::jsonb, 'A hexagon has 6 sides. Think of the cells in a beehive.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030103', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'Every square is also a rectangle.', 'true_false', NULL, '"true"'::jsonb, 'A rectangle has 4 sides and 4 right angles. A square has those too, with all sides the same length, so it''s a special rectangle.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030104', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'Which shape has 5 sides?', 'multiple_choice', '[{"id":"a","text":"hexagon"},{"id":"b","text":"octagon"},{"id":"c","text":"pentagon"},{"id":"d","text":"quadrilateral"}]'::jsonb, '"c"'::jsonb, 'A pentagon has 5 sides.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030105', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'An octagon has ___ sides.', 'fill_blank', NULL, '["8","eight"]'::jsonb, 'An octagon has 8 sides, like a stop sign.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030106', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'A triangle can have two right angles.', 'true_false', NULL, '"false"'::jsonb, 'Two right angles already make 180°, which is all the angles in a triangle added together, so there''d be nothing left for the third angle.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030301', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Put these numbers in order, from smallest to largest.', 'ordering', '[{"id":"a","text":"0.05"},{"id":"b","text":"0.5"},{"id":"c","text":"0.505"},{"id":"d","text":"0.55"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Compare the tenths first, then the hundredths, then the thousandths: 0.05, 0.5, 0.505, 0.55.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030302', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Which number is the largest?', 'multiple_choice', '[{"id":"a","text":"0.68"},{"id":"b","text":"0.7"},{"id":"c","text":"0.699"},{"id":"d","text":"0.07"}]'::jsonb, '"b"'::jsonb, '0.7 has 7 tenths. The others have fewer tenths, so 0.7 is the largest.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030303', '51000000-0000-0000-0000-000000050303', 'medium', 1, '0.4 is the same as 0.40.', 'true_false', NULL, '"true"'::jsonb, '0.40 is 4 tenths and 0 hundredths, which is the same as 0.4.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030304', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Which of these numbers are greater than 0.5? Choose all that apply.', 'multi_select', '[{"id":"a","text":"0.51"},{"id":"b","text":"0.499"},{"id":"c","text":"0.6"},{"id":"d","text":"0.05"},{"id":"e","text":"0.500"}]'::jsonb, '["a","c"]'::jsonb, '0.51 and 0.6 are greater than 0.5. 0.500 is equal to 0.5, not greater.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030305', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'What number is exactly halfway between 0.2 and 0.3?', 'short_answer', NULL, '"0.25"'::jsonb, '0.2 is 0.20 and 0.3 is 0.30. Halfway between 20 hundredths and 30 hundredths is 25 hundredths, or 0.25.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030101', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'What do we call an angle of exactly 90°?', 'multiple_choice', '[{"id":"a","text":"an acute angle"},{"id":"b","text":"a right angle"},{"id":"c","text":"an obtuse angle"},{"id":"d","text":"a straight angle"}]'::jsonb, '"b"'::jsonb, 'An angle of exactly 90° is a right angle, like the corner of a book.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030102', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Angles on a straight line add up to how many degrees?', 'short_answer', NULL, '"180"'::jsonb, 'Angles on a straight line add up to 180°.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030103', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Two angles together make a straight line. One is 65°. How many degrees is the other one?', 'short_answer', NULL, '"115"'::jsonb, 'Angles on a straight line add up to 180°, so the other angle is 180 − 65 = 115°.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030104', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Which of these angles are obtuse? Choose all that apply.', 'multi_select', '[{"id":"a","text":"45°"},{"id":"b","text":"120°"},{"id":"c","text":"90°"},{"id":"d","text":"170°"},{"id":"e","text":"200°"}]'::jsonb, '["b","d"]'::jsonb, 'Obtuse angles are between 90° and 180°, so 120° and 170° are obtuse. 200° is a reflex angle.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030105', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'The angles inside any triangle add up to 180°.', 'true_false', NULL, '"true"'::jsonb, 'The three angles inside every triangle add up to 180°.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030106', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Angles around a point add up to how many degrees?', 'short_answer', NULL, '"360"'::jsonb, 'A full turn is 360°, so angles around a point add up to 360°.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140101', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Which sentence is written correctly?', 'multiple_choice', '[{"id":"a","text":"my dog is called rex."},{"id":"b","text":"My dog is called Rex."},{"id":"c","text":"My dog is called rex"},{"id":"d","text":"my Dog is called Rex."}]'::jsonb, '"b"'::jsonb, 'A sentence starts with a capital letter and ends with a full stop. Rex is a name, so it needs a capital letter too.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140102', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Which of these words should always start with a capital letter? Choose all that apply.', 'multi_select', '[{"id":"a","text":"sydney"},{"id":"b","text":"monday"},{"id":"c","text":"banana"},{"id":"d","text":"emma"},{"id":"e","text":"school"}]'::jsonb, '["a","b","d"]'::jsonb, 'Names of places (Sydney), days (Monday) and people (Emma) always start with a capital letter.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140103', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'A sentence can end with a full stop, a question mark or an exclamation mark.', 'true_false', NULL, '"true"'::jsonb, 'All three can end a sentence. A question mark ends a question and an exclamation mark shows strong feeling.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140104', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Type the punctuation mark that ends this question: Where are you going___', 'fill_blank', NULL, '"?"'::jsonb, 'It''s a question, so it ends with a question mark: Where are you going?', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140105', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Which word in this sentence should start with a capital letter? ''On saturday we went to the beach.''', 'multiple_choice', '[{"id":"a","text":"we"},{"id":"b","text":"saturday"},{"id":"c","text":"went"},{"id":"d","text":"beach"}]'::jsonb, '"b"'::jsonb, 'Days of the week always start with a capital letter: Saturday.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120101', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Which of these words are nouns? Choose all that apply.', 'multi_select', '[{"id":"a","text":"table"},{"id":"b","text":"quickly"},{"id":"c","text":"dog"},{"id":"d","text":"jump"},{"id":"e","text":"city"}]'::jsonb, '["a","c","e"]'::jsonb, 'Nouns name people, places and things: table, dog and city. ''Quickly'' is an adverb and ''jump'' is a verb.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120102', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Which word is the verb in this sentence? ''The children laughed at the funny clown.''', 'multiple_choice', '[{"id":"a","text":"children"},{"id":"b","text":"laughed"},{"id":"c","text":"funny"},{"id":"d","text":"clown"}]'::jsonb, '"b"'::jsonb, 'A verb is a doing word. ''Laughed'' is what the children did.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120103', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Which word is an adjective in this sentence? ''A tiny bird sang outside.''', 'multiple_choice', '[{"id":"a","text":"tiny"},{"id":"b","text":"bird"},{"id":"c","text":"sang"},{"id":"d","text":"outside"}]'::jsonb, '"a"'::jsonb, 'An adjective describes a noun. ''Tiny'' describes the bird.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120104', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'In the sentence ''Mia runs fast'', the word ''runs'' is a verb.', 'true_false', NULL, '"true"'::jsonb, '''Runs'' is what Mia does, so it''s a verb.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120105', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Write the past tense of ''go'' to finish the sentence: Yesterday I ___ to the park.', 'fill_blank', NULL, '"went"'::jsonb, 'The past tense of ''go'' is ''went'': Yesterday I went to the park.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120201', '51000000-0000-0000-0000-000000041202', 'medium', 1, 'Put the words in order to make a sentence.', 'ordering', '[{"id":"a","text":"The"},{"id":"b","text":"dog"},{"id":"c","text":"barked"},{"id":"d","text":"loudly."}]'::jsonb, '["a","b","c","d"]'::jsonb, 'The capital letter shows the first word and the full stop shows the last: The dog barked loudly.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120202', '51000000-0000-0000-0000-000000041202', 'medium', 1, 'Put these events in the order they happened.', 'ordering', '[{"id":"a","text":"Sam woke up and got dressed."},{"id":"b","text":"Sam ate breakfast."},{"id":"c","text":"Sam walked to school."},{"id":"d","text":"The school bell rang."}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Sam got up, had breakfast, walked to school, and then the bell rang.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120203', '51000000-0000-0000-0000-000000041202', 'medium', 1, 'Put these words in alphabetical order.', 'ordering', '[{"id":"a","text":"emu"},{"id":"b","text":"kangaroo"},{"id":"c","text":"koala"},{"id":"d","text":"wombat"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Look at the first letters: e, k, k, w. ''Kangaroo'' and ''koala'' both start with k, so look at the second letters: a comes before o.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140101', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'One dog has a bone. Which is correct?', 'multiple_choice', '[{"id":"a","text":"the dogs bone"},{"id":"b","text":"the dog''s bone"},{"id":"c","text":"the dogs'' bone"},{"id":"d","text":"the dog,s bone"}]'::jsonb, '"b"'::jsonb, 'To show something belongs to one owner, add ''s: the dog''s bone.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140102', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'Write the short form (contraction) of ''do not'': ___', 'fill_blank', NULL, '"don''t"'::jsonb, '''Do not'' becomes ''don''t''. The apostrophe takes the place of the missing o.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140103', '51000000-0000-0000-0000-000000051401', 'medium', 1, '''Its'' with no apostrophe means ''belonging to it''.', 'true_false', NULL, '"true"'::jsonb, '''Its'' means belonging to it (the dog wagged its tail). ''It''s'' is short for ''it is'' or ''it has''.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140104', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'Which sentences use apostrophes correctly? Choose all that apply.', 'multi_select', '[{"id":"a","text":"I can''t come."},{"id":"b","text":"The cat''s tail is long."},{"id":"c","text":"I like apple''s."},{"id":"d","text":"We''re late!"},{"id":"e","text":"The boy''s are playing."}]'::jsonb, '["a","b","d"]'::jsonb, '''Can''t'' and ''we''re'' are contractions, and ''cat''s'' shows the tail belongs to the cat. Plurals like ''apples'' and ''boys'' don''t need an apostrophe.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140105', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'Write the short form (contraction) of ''they are'': ___', 'fill_blank', NULL, '"they''re"'::jsonb, '''They are'' becomes ''they''re''. The apostrophe takes the place of the missing a.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120101', '51000000-0000-0000-0000-000000061201', 'medium', 1, 'Which sentence uses a simile?', 'multiple_choice', '[{"id":"a","text":"The wind howled all night."},{"id":"b","text":"She was as quiet as a mouse."},{"id":"c","text":"The classroom was a zoo."},{"id":"d","text":"Buzz went the bee."}]'::jsonb, '"b"'::jsonb, 'A simile compares two things using ''like'' or ''as'': as quiet as a mouse.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120102', '51000000-0000-0000-0000-000000061201', 'medium', 1, '''The classroom was a zoo.'' What kind of figurative language is this?', 'multiple_choice', '[{"id":"a","text":"simile"},{"id":"b","text":"metaphor"},{"id":"c","text":"onomatopoeia"},{"id":"d","text":"alliteration"}]'::jsonb, '"b"'::jsonb, 'It''s a metaphor: it says the classroom was a zoo, without ''like'' or ''as''.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120103', '51000000-0000-0000-0000-000000061201', 'medium', 1, 'A simile compares two things using ''like'' or ''as''.', 'true_false', NULL, '"true"'::jsonb, 'That''s what makes it a simile, for example ''as brave as a lion''.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120104', '51000000-0000-0000-0000-000000061201', 'medium', 1, 'Which of these words are onomatopoeia? Choose all that apply.', 'multi_select', '[{"id":"a","text":"buzz"},{"id":"b","text":"sizzle"},{"id":"c","text":"happy"},{"id":"d","text":"crash"},{"id":"e","text":"slowly"}]'::jsonb, '["a","b","d"]'::jsonb, 'Onomatopoeia words sound like what they describe: buzz, sizzle and crash.', '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120105', '51000000-0000-0000-0000-000000061201', 'medium', 1, '''The sun smiled down on us.'' What kind of figurative language is this?', 'multiple_choice', '[{"id":"a","text":"personification"},{"id":"b","text":"simile"},{"id":"c","text":"onomatopoeia"},{"id":"d","text":"alliteration"}]'::jsonb, '"a"'::jsonb, 'The sun can''t really smile. Giving human actions to things that aren''t human is personification.', '90000000-0000-0000-0000-000000000001')
